from pathlib import Path
os.environ.setdefault('MPLCONFIGDIR','/private/tmp/fcstgraphics-mpl-cache')
sys.path.insert(0,str(Path(__file__).resolve().parent))
import run_lpi_experiments_20261007 as e
import numpy as np
import matplotlib.pyplot as plt
O=e.OUT;site=e.D.SRC/'site';E=html.escape
L=json.loads((O/'selection_lock.json').read_text());C=json.loads((O/'configs.json').read_text())
def read(file):
 rows=list(csv.DictReader(file.open()))
 for x in rows:
  for k,v in x.items():
   try:x[k]=float(v)
   except ValueError:pass
 return rows
V=read(O/'validation.csv');T=read(O/'test_results.csv');OLD=read(e.r.OUT/'test_metrics.csv');name=L['chosen']['name']
DESC={
'hinge':('Curved ingredient responses','Let each ingredient change its influence at 25%, 50% and 75% of its normalised range. For example, additional instability can matter strongly at low values and flatten at high values. All curve coefficients are learned.','80 learned input terms; two initial shrinkage settings.'),
'interactions':('Ingredient interactions','Add squared terms and 15 pairwise products. This lets the effect of one ingredient depend on another: instability × rain, charging depth × ascent, ascent × subcloud humidity, and others.','55 learned input terms; two initial shrinkage settings, then three refinements.'),
'brier':('Fit probability error directly','Keep the previous model’s 20 predictors and logistic output, but fit by minimising squared probability error—the Brier score—instead of log loss. This changes which mistakes receive the greatest training penalty.','Two shrinkage settings; the optimisation is not guaranteed to find a global minimum.'),
'rbf':('Weather-pattern similarity','Choose 32 reproducible training examples as prototype ingredient patterns. Measure how similar a forecast is to each pattern, then learn which similarities increase or reduce lightning probability. The original predictors remain available.','32 Gaussian similarity functions plus 20 original terms; fixed width 3 in standardised feature space; two shrinkage settings.'),
'random_network':('Nonlinear network','Pass ingredients through 32 fixed, reproducible nonlinear combinations, then learn how to combine those responses with the original 20 predictors. This can represent weather regimes and interactions that were not explicitly specified.','One fixed random hidden layer; only output weights are learned. Two initial shrinkage settings and three refinements; one seed, not a fully trained deep network.'),
'gaussian':('Lightning / no-lightning pattern classifier','Learn a multivariate ingredient distribution separately for lightning and non-lightning cases. Compare how well a forecast fits each distribution and fit a logistic conversion to probability.','Two covariance-shrinkage settings (0.1 and 0.6); means, covariances and probability conversion use training cases only.')}

def table(rows,cols):
 def val(v):return f'{v:+.2f}' if isinstance(v,float) else E(str(v))
 return '<div class="scroll"><table><tr>'+''.join('<th>'+E(label)+'</th>' for k,label in cols)+'</tr>'+''.join('<tr>'+''.join('<td>'+val(x.get(k,''))+'</td>' for k,label in cols)+'</tr>' for x in rows)+'</table></div>'
def subset(n,d='24h',coverage='available',dom='all_bc'):return [x for x in T if x['name']==n and x['duration']==d and x['coverage']==coverage and x['domain']==dom]
def pooled(rs):return sum(x['n']*x['brier'] for x in rs)/sum(x['n'] for x in rs)
def refpool(rs):return sum(x['n']*x['reference_brier'] for x in rs)/sum(x['n'] for x in rs)
summary=[]
for family in DESC:
 rank=next(x for x in L['ranking'] if x['family']==family);n=rank['name'];rs=subset(n);row=dict(family=DESC[family][0],candidate=n,validation=100*(1-rank['ratio']),test=100*(1-pooled(rs)/refpool(rs)))
 row.update({x['fold']:x['gain_percent'] for x in rs});summary.append(row)
summary.sort(key=lambda x:-x['validation'])
bestnew=summary[0]['candidate'];selected=subset(name) if name!='previous_winner' else []
passed=bool(selected) and all(x['ci_day_high']<0 and x['ci_3day_high']<0 and x['auc_delta']>=-.02 for x in selected+subset(name,coverage='12hours'))
focus=name if selected else bestnew;frows=subset(focus);gain=100*(1-pooled(frows)/refpool(frows))
base=[x for x in OLD if x['name']=='baseline' and x['domain']=='all_bc' and x['duration']=='24h'];basepool=sum(x['weighted_cells']*x['brier'] for x in base)/sum(x['weighted_cells'] for x in base)
overall=100*(1-pooled(frows)/basepool)
fig,ax=plt.subplots(figsize=(10,5),constrained_layout=True);pos=np.arange(len(summary));ax.barh(pos-.18,[x['validation'] for x in summary],height=.35,label='Validation: used to choose');ax.barh(pos+.18,[x['test'] for x in summary],height=.35,label='Later test: reported after selection');ax.set_yticks(pos,[x['family'] for x in summary]);ax.invert_yaxis();ax.axvline(0,color='#555');ax.set_xlabel('Daily Brier improvement versus previous winner (%)');ax.legend();fig.savefig(O/'families.png',dpi=160);plt.close(fig)
style='''body{margin:0;background:#f1f5f6;color:#17343c;font:18px/1.65 system-ui,sans-serif}main{max-width:1140px;margin:auto;padding:40px 28px 90px}h1{font-size:42px;line-height:1.15}h2{margin-top:48px}p{max-width:960px}.lead{font-size:23px}.card{background:white;border-left:6px solid #137c87;padding:22px 28px;margin:24px 0}.scroll{overflow:auto}table{border-collapse:collapse;background:white;width:100%;font-size:15px}th,td{padding:12px;text-align:left;border-bottom:1px solid #d5e0e3;vertical-align:top}th{background:#dcebed}code{font-size:14px;overflow-wrap:anywhere}a{color:#086b80}img{width:100%}.muted{color:#536970}li{margin:9px 0}nav a{margin-right:18px}footer{border-top:1px solid #aab;margin-top:40px;font-size:14px}'''
p=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LPI formulation experiments — 7 October 2026</title><style>'+style+'</style><main>', '<p class="muted">LPI research · 7 October 2026 · British Columbia · day-one forecasts</p><h1>Can a more flexible formula improve on the learned LPI?</h1>', '<nav><a href="#results">Results</a><a href="#methods">What changed</a><a href="#refine">Refinement</a><a href="#dates">Dates and coverage</a><a href="#recommend">Recommendation</a></nav>']
headline=('The previous model remains the selected choice.' if name=='previous_winner' else 'The validation rule selected the '+DESC[next(c['family'] for c in C if c['name']==name)][0].lower()+'.')
p.append(f'<div class="card"><p class="lead">{headline}</p><p>I tested <b>18 new candidates across six model families</b>, including six refinements. The strongest new family on daily validation was the nonlinear network. Its best candidate reduced validation error by {summary[0]["validation"]:.2f}% relative to the previous winner. On the later test cases, that candidate changed daily Brier error by {summary[0]["test"]:+.2f}% improvement.</p><p><b>'+('The selected candidate passed the specified period-by-period uncertainty checks.' if passed else 'This round does not establish a dependable improvement over the previous winner.')+'</b></p></div>')
p.append('<h2 id="results">1. What the results mean</h2><p>Every percentage in the main comparison is measured against the previous learned model, which already improved substantially on the original recipe. Positive means less error; negative means more error. Brier score averages (forecast probability − observed outcome)², with the observation coded 1 for lightning and 0 for no lightning. A 1% improvement means 1% less of that probability error; it does not mean 1% more storms detected.</p><p>The target is lightning within 30 km during the full 24-hour forecast day, 12Z to the next 12Z. The new daily models use all eligible BC locations, not just locations near transmission lines.</p>')
p.append('<img alt="Validation and test error improvements for six algorithm families" src="data:image/png;base64,'+base64.b64encode((O/'families.png').read_bytes()).decode()+'">')
p.append(table(summary,[('family','Model family'),('validation','Mean validation gain (%)'),('summer','August test gain (%)'),('late_summer','Late-summer test gain (%)'),('autumn','Autumn test gain (%)'),('test','Pooled daily test gain (%)')]))
p.append('<p>This table shows the best daily-validation candidate from each family. It explains what transferred from development into later dates. Validation averages the three period-relative scores equally. The pooled test score weights each eligible grid-cell day equally, so periods with more usable locations have more influence. The test column did not determine which candidate was refined or selected.</p>')
p.append('<h2 id="methods">2. Exactly what I changed</h2><p>The previous winner learns a weighted sum of 20 forecast summaries and converts it to a probability. Those summaries describe ingredient peaks, means, persistence, and simultaneous favourable ingredients. This round holds those inputs fixed and changes the mathematical relationship between them and lightning. No new solar, geography, or observation inputs were added.</p>')
p.append(table([dict(family=v[0],idea=v[1],implementation=v[2]) for v in DESC.values()],[('family','Approach'),('idea','Plain-language explanation'),('implementation','What was varied')]))
p.append('<p>The curved-response, interaction, and direct-Brier models build directly on the previous successful formulation. The prototype-pattern model, nonlinear network, and distribution classifier use different ways of representing the relationship. These experiments do not test new raw meteorological ingredients or replace the fixed 20 km spatial smoothing.</p><p>All models are fitted on the same approximately 10 km training lattice and scored on every eligible 5 km grid cell. Standardisation, prototype selection, means and covariances use only training data. The random network uses a fixed seeded hidden layer; fitting adjusts the output coefficients. Except for the direct-Brier model, the fitted output minimises log loss with a penalty on large coefficients.</p>')
p.append('<h2 id="refine">3. What was refined, and how the final choice was made</h2><p>Each family started with two settings. The two distinct families with the best daily validation scores and no period AUC loss larger than 0.02 received three additional settings each. Those families were the nonlinear network and ingredient interactions. Refinement varied the penalty on large fitted weights; it refitted every coefficient on training data at each setting. It did not vary network size, random seed, or spatial radius.</p>')
ref=[]
for c in C:
 if c['family'] not in L['refined_families']:continue
 rank=next(x for x in L['ranking'] if x['name']==c['name']);ref.append(dict(family=DESC[c['family']][0],stage='Refinement' if 'refine' in c['name'] else 'Initial',penalty=f"{c['param']:g}",gain=100*(1-rank['ratio'])))
p.append(table(ref,[('family','Family'),('stage','Stage'),('penalty','Weight penalty'),('gain','Daily validation gain (%)')]))
p.append('<p>A smaller penalty gives the model more freedom to fit complicated relationships. Refinement did not beat the best initial network setting. The interaction model improved only from a 0.101% to a 0.109% validation gain—an immaterial change. More searching therefore did not produce a meaningful development gain here.</p>')
p.append(f'<p>The best daily-validation candidate was <code>{E(L["best_daily"]["name"])}</code>. The final selection was <code>{E(name)}</code>. We allow a candidate within 1% of the best daily validation error to replace it only if its three-hour validation error is at least 2% lower. The previous winner is included in this choice.</p>')
ties=[dict(candidate=n,daily=100*(1-(next((x['ratio'] for x in L['ranking'] if x['name']==n),1.))),three=100*(1-v)) for n,v in L['three_hour_ratios'].items()]
p.append(table(ties,[('candidate','Candidate with 3-hour evaluation'),('daily','Daily validation gain (%)'),('three','Three-hour validation gain (%)')]))
p.append('<p>Daily and three-hour models are fitted separately. This lets the secondary score influence architecture selection without treating a daily probability as a three-hour probability. I saved the selection before evaluating any new model on test dates. These historical dates have nevertheless been used in earlier research rounds, so this is retrospective evidence, not an untouched confirmation experiment.</p>')
p.append('<h2>4. Are the small differences dependable?</h2><p>The following uncertainty results concern <code>'+E(focus)+'</code>. A negative change in Brier score is good. An interval spanning zero means these test days do not reliably distinguish the new model from the previous winner.</p>')
ci=[]
for x in frows:
 row=dict(period=x['fold'],gain=x['gain_percent'],delta=f"{x['brier']-x['reference_brier']:+.6f}",day=f"[{x['ci_day_low']:+.6f}, {x['ci_day_high']:+.6f}]",block=f"[{x['ci_3day_low']:+.6f}, {x['ci_3day_high']:+.6f}]",auc=x['auc_delta']);ci.append(row)
p.append(table(ci,[('period','Test period'),('gain','Daily gain (%)'),('delta','Brier change'),('day','95% day-resampling interval'),('block','95% three-day interval'),('auc','AUC change')]))
p.append('<p>The screening gate requires both intervals to stay below zero in every period, no AUC loss greater than 0.02, and the same result after restricting verification centres to at least 12 valid ingredient hours. These intervals resample weather days, keeping spatial cells together. The second version resamples circular groups of three consecutive available days. Neither accounts for uncertainty from retraining or searching many models, and gaps mean three available days need not be three consecutive calendar dates.</p>')
sens=[]
for x in frows:
 s=next(z for z in subset(focus,coverage='12hours') if z['fold']==x['fold']);b=next(z for z in subset(focus,'3h') if z['fold']==x['fold']);co=next(z for z in subset(focus,dom='corridor') if z['fold']==x['fold']);sens.append(dict(period=x['fold'],daily=x['gain_percent'],half=s['gain_percent'],three=b['gain_percent'],corridor=co['gain_percent']))
p.append(table(sens,[('period','Period'),('daily','All-BC daily gain (%)'),('half','At least 12 valid hours (%)'),('three','All-BC 3-hour gain (%)'),('corridor','Corridor daily gain (%)')]))
p.append('<p>The 12-hour check holds the fitted model fixed and restricts the verification centres; it does not repair missing hours in surrounding cells. Corridor results use the new all-BC model over corridor locations. The older corridor reference was fitted specifically for the corridor, so that column combines a change in formulation with a change in training domain and is secondary evidence.</p>')
p.append('<h2 id="dates">5. Dates, coverage, and the limits of this archive</h2><p>Training dates teach the coefficients. Validation dates choose the formulation and penalty. Test dates report how the chosen settings behave later. Each row below is a separate chronological fit. Buffers separate these sets, and whole issued forecast runs are excluded if their two-day windows cross a boundary. The raw ingredient study itself uses day one only.</p>')
dates=[]
for fold,splits in e.D.FOLDS.items():
 row=dict(period=fold)
 for stage in ('train','validate','test'):
  ids=e.r.fold_ids(fold,stage);ds=[e.r.CASES[i]['day'] for i in ids];row[stage]=' to '.join(splits[stage])+f'; {len(ids)} usable runs, actual {min(ds)} to {max(ds)}'
 dates.append(row)
p.append(table(dates,[('period','Evaluation'),('train','Training'),('validate','Validation'),('test','Test')]))
p.append('<p>The underlying cohort contains 62 day-one forecasts issued at 12Z. The archived observation cutoff remains 5 October 2026 at 12Z. Full day-two hourly ingredients are unavailable, so these results do not establish a day-two formulation. Summer is represented, but this is a short partial season and cannot establish an annual solar-angle effect.</p><p>Some derived ingredient values are undefined even when an archive file exists. The analysis uses hours where all ten required source fields are finite, summarises only those available hours, and requires 95% valid spatial-kernel support. All models use identical eligibility masks. Daily targets require all eight three-hour observation blocks. Main test coverage is roughly 80%, 61% and 44% of the BC analysis area in the three periods; it falls to roughly 65%, 46% and 30% in the 12-hour sensitivity. Active-lightning test days number 11, 6 and 8. This uneven support is a substantial limitation.</p>')
p.append('<h2 id="recommend">6. Recommendation and justification</h2>')
p.append('<p><b>'+('Retain the selected candidate as a research challenger and seek independent confirmation before operational adoption.' if passed else 'Use the nonlinear network as the provisional preferred formulation, with the previous winner as the benchmark and fallback.')+'</b> '+('Its gains meet the specified retrospective screening gate, but repeated use of the archive still limits confidence.' if passed else 'Its measured daily gains were positive in all three test periods. The user has approved implementation after reviewing the uncertainty; the incremental gain still fails the strict period-by-period gate and needs independent confirmation.')+'</p>')
p.append(f'<p>The strongest new daily-validation candidate has a pooled daily test gain of {summary[0]["test"]:+.2f}% relative to the previous winner. For the detailed candidate above, the corresponding total improvement versus the original recipe with the same 20 km smoothing is {overall:.2f}% on this exact cohort. This total is computed from the scores; percentages from different rounds must not be added.</p><ul><li><b>Keep the nonlinear network as a challenger.</b> It was the strongest new family during validation. Freeze its settings before gathering a genuinely new verification period.</li><li><b>Prefer independent data over a larger search on these same dates.</b> Another large parameter search can make validation look better without improving future forecasts.</li><li><b>Improve hourly support and acquire complete day-two ingredients.</b> This would permit fuller seasonal coverage and an honest test of whether the optimal formulation or smoothing changes with lead time.</li><li><b>Keep the daily-first selection rule.</b> Three-hour skill remains a useful secondary criterion when daily performance is essentially tied.</li></ul><p>The new formulation is implemented for every HRDPS cycle through F048. These retrospective skill results cover continental 12Z day one; other cycles and day two transfer the frozen coefficients and need independent verification.</p>')
p.append('<h2>7. Reproduce or inspect the work</h2><p><a href="advanced/lpi_experiments_20261007.zip">Download report, tables, protocol, saved fits and scripts</a> · <a href="radical_report.html">Previous radical-formulation report</a> · <a href="daily_review_report.html">Earlier daily / smoothing review</a></p><p>The download contains all validation candidates, the locked choice, test results for one validation-chosen representative per family, model parameters, and checks. Scoring all test representatives is descriptive and does not reopen selection. The large archived forecast arrays remain on the Studio.</p><footer>Prepared 7 October 2026. Available-input cohort; retrospective research. Private Studio hosting.</footer></main></html>')
text=''.join(p)
implementation = '''<section class="card" id="deployment"><h2>Implementation approved - 7 October 2026</h2><p>The nonlinear network is now the provisional preferred LPI. The forecast code uses it for all HRDPS cycles (00Z, 06Z, 12Z and 18Z) at F003 through F048, with separate three-hour and directly fitted 24-hour probabilities. F000 is labelled an initialization diagnostic. The active public product is continental HRDPS. Day two and other cycles transfer the frozen day-one weights; the research scores do not establish their skill. The final coefficients were refitted on all 62 frozen cases; the verification results below belong to the earlier chronological test fits.</p><p><a href="implementation/lpi_quick_reference.pdf">Download the one-page LPI and dry-lightning quick reference</a> | <a href="https://github.com/gwest1000/fcst-graphics/tree/codex/lpi-v4">Implementation repository</a></p><details><summary>Today's generated examples</summary><p>The direct daily forecast has limited valid coverage because many derived charging-layer ingredients are undefined. Grey or blank support areas must not be read as zero risk.</p><img src="implementation/daily_example.png" alt="Direct daily probability forecast for 7 October 12Z through 8 October 12Z"><img src="implementation/three_hour_example.png" alt="Three-hour fire-weather forecast using the learned LPI"></details><p>The public Fire Weather plots for the 7 October 12Z run have been regenerated at every three-hour horizon through F048. Observation-complete daily verification for the 6 October 00Z, 06Z and 12Z runs now uses the new directly fitted daily model. A 12Z run has two daily verification windows, ending F024 and F048; the second is published once its observations are complete. The HRDPS Convective 4-Panel also replaces LI contours with the same three-hour LPI probability in its IPW/CAPE panel. The 7 October 12Z run is regenerated through F048. The measured 19.53% daily gain is against the previous LPI recipe, not a standalone LI benchmark. Older retained runs keep their original formulation labels. <a href="https://gwest1000.github.io/fcst-graphics/">Open the live forecast viewer</a>.</p></section>'''
text=text.replace('<h2 id="results">',implementation+'<h2 id="results">',1)
(O/'report.html').write_text(text)
P=e.P;P.write_json(O/'recommendation.json',dict(selected=name,passed_gate=passed,focus=focus,focus_test_gain=gain,focus_total_gain_vs_recipe=overall,best_new_daily_candidate=bestnew))
